void ListOrdGrp::reset() noexcept {
	m_NoOrdersGroup.clear();
	m_presence = 0;
}

bool ListOrdGrp::checkRequired() const noexcept {
	if ((m_presence & REQUIRED) != REQUIRED) {
		return false;
	}
	for (const auto &entry : m_NoOrdersGroup) {
		if (!entry.checkRequired()) {
			return false;
		}
	}
	return true;
}

bool ListOrdGrp::decode(const char *&p, const char *end) noexcept {
	return decode(p, end, 0, false);
}

bool ListOrdGrp::decode(const char *&p, const char *end, int32_t stop_tag, bool stop_on_repetition) noexcept {
	bool consumed = false;
	while (p < end) {
		const char *tag_start = p;
		int32_t tag = 0;
		while (p < end && *p != '=') {
			const unsigned d = static_cast<unsigned>(*p - '0');
			if (d > 9) { return false; }
			tag = tag * 10 + static_cast<int32_t>(d);
			++p;
		}
		if (p >= end) { return false; }
		if (stop_on_repetition && consumed && tag == stop_tag) {
			p = tag_start;
			break;
		}
		switch (tag) {
		case field_id::NoOrders: {
			++p;
			const char *valueBegin = p;
			while (p < end && *p != fix44::serialize::SOH) { ++p; }
			if (p >= end) { return false; }
			const char *valueEnd = p;
			++p;
			const int64_t count_i64 = falconfix::atoi(valueBegin, valueEnd);
			if (count_i64 < 0) { return false; }
			const std::size_t count = static_cast<std::size_t>(count_i64);
			m_NoOrdersGroup.clear();
			m_NoOrdersGroup.reserve(count);
			for (std::size_t i = 0; i < count; ++i) {
				m_NoOrdersGroup.emplace_back();
				if (!m_NoOrdersGroup.back().decode(p, end)) { return false; }
			}
			consumed = true;
			continue;
		}
		default:
			p = tag_start;
			return consumed;
		}
	}
	return consumed;
}

char *ListOrdGrp::encode(char *p, bool includeMilliseconds) const noexcept {
	if (!m_NoOrdersGroup.empty()) {
		WRITE_TAG3(fix44::tag_const::NoOrders);
		p += falconfix::itoa(static_cast<int64_t>(m_NoOrdersGroup.size()), p);
		*p++ = fix44::serialize::SOH;
		for (const auto &entry : m_NoOrdersGroup) {
			if ((p = entry.encode(p, includeMilliseconds)) == nullptr) { return nullptr; }
		}
	}
	return p;
}

bool ListOrdGrp::setField(int32_t, const char *, const char *) noexcept {
	return false;
}

